def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    dangerous_prev = 0.0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0.0)
            prev_bids.append(bid)
            if opp.get('budget', 0) > 0 and bid > dangerous_prev:
                dangerous_prev = bid

    alive_count = len(alive)
    req_pressure = (alive_count + 1) * WATER_REQ
    tight_supply = supply <= req_pressure
    very_tight = supply <= req_pressure - WATER_REQ

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if very_tight:
        urgency += 2
    elif tight_supply:
        urgency += 1

    if day >= 8:
        urgency += 1

    if dangerous_prev <= 0:
        if urgency >= 5:
            bid = DAILY_SALARY * 0.9
        elif urgency >= 3:
            bid = DAILY_SALARY * 0.62
        elif tight_supply:
            bid = DAILY_SALARY * 0.48
        else:
            bid = DAILY_SALARY * 0.32
    else:
        if urgency >= 5:
            bid = max(DAILY_SALARY * 0.9, dangerous_prev + 2.0)
        elif urgency >= 3:
            bid = max(DAILY_SALARY * 0.68, dangerous_prev + 1.2)
        elif tight_supply:
            bid = max(DAILY_SALARY * 0.52, dangerous_prev + 0.8)
        else:
            if dangerous_prev >= DAILY_SALARY * 1.8:
                bid = DAILY_SALARY * 0.22
            elif dangerous_prev >= DAILY_SALARY * 1.2:
                bid = DAILY_SALARY * 0.3
            else:
                bid = max(DAILY_SALARY * 0.38, dangerous_prev * 0.72)

    if hp >= 8 and no_water_days == 0 and not tight_supply:
        bid = min(bid, DAILY_SALARY * 0.28)

    if budget < DAILY_SALARY * 0.8 and urgency < 4:
        bid = min(bid, budget * 0.55)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents alive, conserve budget.
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only.
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
                prev_hp_after.append(int(pt.get('hp_after', o.get('hp', 0))))
            except Exception:
                pass

    # Estimate opponent pressure.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

    # Supply-based aggressiveness: medium scenario => supply often in [15,25].
    # If supply is high, competition is lower; if low, competition is higher.
    if supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        supply_factor = 1.0
    else:
        supply_factor = 0.75

    # If I'm in danger (low hp or many no-water days), bid harder.
    danger = (my_hp <= 2) or (my_no_water_days >= 2)

    # Cindy likely paid to survive (yesterday avg ~142). If she was high bidder, match/just beat.
    # Strategy: bid slightly above the highest yesterday bid when my situation is not safe.
    target = None
    if highest_prev_bid > 0:
        if danger:
            # Just over the likely winning bid.
            target = (highest_prev_bid + 5.0) * supply_factor
        else:
            # Moderate: try to beat without overpaying.
            target = max(DAILY_SALARY * 0.55, (second_prev_bid + 3.0) * supply_factor)
            # If Cindy was extremely aggressive, still tilt up.
            if highest_prev_bid >= DAILY_SALARY * 1.2:
                target = max(target, (highest_prev_bid - 10.0) * supply_factor)
    else:
        target = DAILY_SALARY * (0.9 if danger else 0.6) * supply_factor

    # Cap by budget.
    bid = max(0.0, min(my_budget, float(target)))

    # Ensure we don't bid trivially low when supply is scarce.
    if supply <= MIN_SUPPLY + 1.0:
        bid = max(bid, DAILY_SALARY * (0.7 if danger else 0.55))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
